"""Writes reference values for the annual aberration tests, using pyerfa.

Run from the repository root with a Python that has `pyerfa` and `numpy`:

    python tpt-planetary-astro/tests/fixtures/gen_aberration_fixture.py

Writes `aberration_erfa.tsv`, one line per case:

    ra_deg dec_deg jd1 jd2 vx vy vz ara_deg adec_deg

where (ra, dec) is the ICRS direction without aberration, (jd1, jd2) the TT
epoch as a two-part Julian date, (vx, vy, vz) the Earth's barycentric velocity
in AU/day from `erfa.epv00`, and (ara, adec) the aberrated direction from
`erfa.ab` (which takes the velocity in units of c). The Rust test uses the
same velocity, so the comparison checks the aberration formula itself.
"""

import os

import erfa
import numpy as np

HERE = os.path.dirname(os.path.abspath(__file__))
C_AU_PER_DAY = 173.1446326846693


def main():
    rng = np.random.default_rng(7)
    rows = []
    epochs = [(2451545.0, 0.0), (2460000.5, 0.25), (2415020.5, 0.0), (2488069.5, 0.5)]
    for jd1, jd2 in epochs:
        for _ in range(12):
            ra = rng.uniform(0.0, 360.0)
            dec = np.degrees(np.arcsin(rng.uniform(-1.0, 1.0)))
            pnat = np.array(
                [
                    np.cos(np.radians(dec)) * np.cos(np.radians(ra)),
                    np.cos(np.radians(dec)) * np.sin(np.radians(ra)),
                    np.sin(np.radians(dec)),
                ]
            )
            pvh, pvb = erfa.epv00(jd1, jd2)
            vel = np.asarray(pvb[1], dtype=float)
            v_over_c = vel / C_AU_PER_DAY
            # erfa.ab(pnat, v, s, bm1): s is the Sun-observer distance in AU.
            sun_dist = float(np.linalg.norm(np.asarray(pvh[0], dtype=float)))
            bm1 = np.sqrt(1.0 - np.dot(v_over_c, v_over_c))
            ppr = np.asarray(erfa.ab(pnat, v_over_c, sun_dist, bm1), dtype=float)
            ara = float(np.degrees(np.arctan2(ppr[1], ppr[0])) % 360.0)
            adec = float(np.degrees(np.arcsin(np.clip(ppr[2], -1.0, 1.0))))
            rows.append(
                "%.12f %.12f %.10f %.10f %.12e %.12e %.12e %.12f %.12f"
                % (ra, dec, jd1, jd2, vel[0], vel[1], vel[2], ara, adec)
            )
    path = os.path.join(HERE, "aberration_erfa.tsv")
    with open(path, "w") as f:
        f.write("# ra_deg dec_deg jd1 jd2 vx vy vz (AU/day) ara_deg adec_deg; generated by pyerfa %s\n" % erfa.__version__)
        f.write("\n".join(rows) + "\n")
    print("wrote", len(rows), "cases to", path)


if __name__ == "__main__":
    main()
